function canonicalBrandName(raw){
  const name=String(raw||'').trim();
  if(name==='Early Ronson / Art Metal Works')return 'Ronson';
  return name
    .replace(/（(?:重要早期款|早期|重要老款|現代款|普通現代款|現代 disposable|大眾款)）/gi,'')
    .trim();
}


const BRAND_NAME_MIGRATIONS=Object.fromEntries((window.LIGHTERS||[]).map(x=>[x.name,canonicalBrandName(x.name)]).filter(([a,b])=>a!==b));
const TIER_ORDER=['全部','S+','S','A+','A','A-','B+','B','C+','C','D','F'];
const readStore=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}};
const writeStore=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
function normalizeTier(raw,name=''){
  const display=displayBrandName(name),t=String(raw||'').trim();
  if(display==='Zippo')return 'A+';
  if(t==='S～A+')return 'A+';
  if(t==='B（現代）')return 'B';
  if(t==='A-/B+')return 'B+';
  return TIER_ORDER.includes(t)?t:'B';
}
function displayBrandName(name){const base=canonicalBrandName(name);return base.split(' / ')[0].trim()||base}
function shouldOmitLogo(name){return /重要設計者|發明者|Prototype|Patent Lighter|無牌|souvenir|advertising|Generic OEM|Counterfeit|仿冒/i.test(String(name||''))}
function brandLogoLabel(name){let label=displayBrandName(name).replace(/^Early\s+/i,'').trim();if(/^S\.T\. Dupont$/i.test(label))return 'S.T. DUPONT';return label}
function svgEsc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function makerMarkData(name){
  const label=brandLogoLabel(name),words=label.split(/\s+/).filter(Boolean);let lines=[];
  if(label.length<=13)lines=[label];else if(words.length>=2){const cut=Math.ceil(words.length/2);lines=[words.slice(0,cut).join(' '),words.slice(cut).join(' ')]}else lines=[label.slice(0,13),label.slice(13)];
  const fs=lines.some(v=>v.length>15)?25:lines.some(v=>v.length>11)?29:34,y=lines.length===1?99:78;
  const txt=lines.map((v,i)=>`<text x='180' y='${y+i*40}' text-anchor='middle' font-family='Arial,Helvetica,sans-serif' font-size='${fs}' font-weight='800' fill='#111'>${svgEsc(v)}</text>`).join('');
  const svg=`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 360 190'><rect width='360' height='190' rx='22' fill='#fff'/><rect x='7' y='7' width='346' height='176' rx='18' fill='none' stroke='#d9d9d9' stroke-width='2'/>${txt}</svg>`;
  return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)
}
const LOGO_OVERRIDES=window.LIGHTER_REAL_LOGOS||window.LIGHTER_LOGO_OVERRIDES||{};
const LOGO_DOMAINS=window.LIGHTER_LOGO_DOMAINS||{};
