let all=[];
function rebuildBrands(){
  const rank=brandRankOverrides(),origin=brandOriginOverrides(),seen=new Set(),out=[];
  for(const src of [...(window.LIGHTERS||[]),...customBrands()]){
    const name=canonicalBrandName(src.name),key=name.toLocaleLowerCase();if(!name||seen.has(key))continue;seen.add(key);
    out.push({...src,name,custom:!!src.custom,tier:rank[name]||normalizeTier(src.tier,name),origin:origin[name]||src.origin||''});
  }
  all=out;
}
