const getJSON=readStore,setJSON=writeStore;
function migrateBrandNames(){
  const mapName=n=>BRAND_NAME_MIGRATIONS[n]||n;
  const db=getJSON('lighterModels',{}),nextDb={};
  for(const [name,arr] of Object.entries(db)){const k=mapName(name);nextDb[k]=[...(nextDb[k]||[]),...(Array.isArray(arr)?arr:[])]}
  setJSON('lighterModels',nextDb);
  const fav=[...new Set(getJSON('lighterSaved',[]).map(mapName))];setJSON('lighterSaved',fav);
  for(const key of ['lighterBrandNotes','lighterBrandAliases']){const src=getJSON(key,{}),dst={};for(const [name,val] of Object.entries(src)){const k=mapName(name);if(Array.isArray(val))dst[k]=[...new Set([...(dst[k]||[]),...val])];else if(!dst[k])dst[k]=val}setJSON(key,dst)}
}
