function norm(s){return(s||'').toLowerCase().normalize('NFKD')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return''}}
function uid(){return crypto.randomUUID?crypto.randomUUID():'m-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
function normalizeModel(m){return {
  id:m.id||uid(),collectionNo:m.collectionNo||'',model:m.model||'',url:m.url||'',owned:!!m.owned,favorite:!!m.favorite,added:m.added||new Date().toISOString(),
  estimatedDate:m.estimatedDate||'',mechanism:m.mechanism||'',authenticity:m.authenticity||'',researchNotes:m.researchNotes||'',aiHistoryIds:Array.isArray(m.aiHistoryIds)?m.aiHistoryIds:[],maintenance:Array.isArray(m.maintenance)?m.maintenance:[],
  purchaseYear:m.purchaseYear||'',purchaseDate:m.purchaseDate||'',price:m.price??'',currency:m.currency||'TWD',source:m.source||'',sourceOther:m.sourceOther||'',seller:m.seller||'',purchaseLocation:m.purchaseLocation||'',condition:m.condition||'未評估',serial:m.serial||'',notes:m.notes??m.note??''
}}
function ensureModelIds(){let db=models(),changed=false;Object.keys(db).forEach(k=>{db[k]=db[k].map(m=>{const n=normalizeModel(m);if(JSON.stringify(n)!==JSON.stringify(m))changed=true;return n})});if(changed)setJSON('lighterModels',db)}
function nextCollectionNo(db=models()){let max=0;for(const arr of Object.values(db))for(const m0 of arr){const m=normalizeModel(m0),hit=String(m.collectionNo||'').match(/^L(\d+)$/i);if(hit)max=Math.max(max,Number(hit[1])||0)}return 'L'+String(max+1).padStart(4,'0')}
function collectionNoExists(value,db=models(),currentId=''){const n=norm(String(value||'').trim());if(!n)return false;for(const arr of Object.values(db))for(const m0 of arr){const m=normalizeModel(m0);if(m.id!==currentId&&norm(String(m.collectionNo||'').trim())===n)return true}return false}
function ensureCollectionNumbers(){let db=models(),changed=false,max=0;for(const arr of Object.values(db))for(const m0 of arr){const hit=String(m0.collectionNo||'').match(/^L(\d+)$/i);if(hit)max=Math.max(max,Number(hit[1])||0)}for(const brand of Object.keys(db)){db[brand]=db[brand].map(m0=>{const m=normalizeModel(m0);if(m.owned&&!m.collectionNo){m.collectionNo='L'+String(++max).padStart(4,'0');changed=true}return m})}if(changed)setJSON('lighterModels',db)}
