function fileToLogoDataURL(file){return new Promise((resolve,reject)=>{if(!file||!file.type.startsWith('image/'))return reject(new Error('請選擇圖片檔'));const r=new FileReader();r.onerror=()=>reject(r.error);r.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('圖片無法讀取'));img.onload=()=>{const maxW=900,maxH=520,scale=Math.min(1,maxW/img.width,maxH/img.height),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);let out;try{out=c.toDataURL('image/webp',.9);if(!out.startsWith('data:image/webp'))out=c.toDataURL('image/png')}catch{out=c.toDataURL('image/png')}resolve(out)};img.src=r.result};r.readAsDataURL(file)})}
function rankSelect(value,id='brandRankSelect'){return `<select id="${id}">${TIER_ORDER.slice(1).map(t=>`<option value="${t}" ${t===value?'selected':''}>${t}</option>`).join('')}</select>`}
function brandSettingsHTML(x){const userLogo=brandLogoOverrides()[x.name]||'',urlVal=/^https?:/i.test(userLogo)?userLogo:'',hasDefault=!!defaultLogo(x.name);return `<details class="brand-section brand-settings-section"><summary><span>品牌設定</span><small>Rank、起源、Logo</small></summary><div class="brand-section-body brand-settings-body"><div class="brand-settings-grid"><div class="field"><label>收藏 Rank</label>${rankSelect(x.tier)}</div><div class="field"><label>起源國家</label><input id="brandOriginInput" value="${esc(originLabel(x)==='未查'?'':originLabel(x))}" placeholder="例如 瑞士"></div></div>${shouldOmitLogo(x.name)?'<p class="settings-note">這筆是設計者 / 發明者 / Prototype 類型，因此不顯示 Logo。</p>':`<div class="logo-editor"><div class="logo-editor-preview">${brandLogoHTML(x.name,'setting')}</div><div class="logo-editor-controls"><label>Logo 圖片網址</label><div class="input-with-action"><input id="brandLogoUrl" type="url" value="${esc(urlVal)}" placeholder="https://…"><button type="button" id="applyLogoUrl">套用</button></div><label class="logo-upload">上傳 / 更換 Logo<input id="brandLogoFile" type="file" accept="image/*"></label><div class="logo-editor-actions"><button type="button" id="resetBrandLogo" class="secondary">${hasDefault?'還原內建 Logo':'清除自訂 Logo'}</button></div><small>建議透明 PNG / SVG 或清楚橫向 Logo；上傳圖片會存在此裝置並包含在完整備份。</small></div></div>`}<div class="brand-settings-actions"><button type="button" id="saveBrandSettings">儲存 Rank / 起源</button>${x.custom?'<button type="button" id="deleteCustomBrand" class="danger">刪除這個自訂品牌</button>':''}</div></div></details>`}
function bindBrandSettings(x){const save=detail.querySelector('#saveBrandSettings');if(save)save.onclick=()=>{const ranks=brandRankOverrides(),origins=brandOriginOverrides();ranks[x.name]=detail.querySelector('#brandRankSelect').value;const o=(detail.querySelector('#brandOriginInput').value||'').trim();if(o)origins[x.name]=o;else delete origins[x.name];setJSON('lighterBrandRanks',ranks);setJSON('lighterBrandOrigins',origins);rebuildBrands();renderFilters();render();openBrand(x.name,currentEditIndex,null,'replace')};const apply=detail.querySelector('#applyLogoUrl'),url=detail.querySelector('#brandLogoUrl');if(apply&&url)apply.onclick=()=>{const v=url.value.trim();if(v&&!safeUrl(v))return alert('請輸入 http / https 圖片網址');const map=brandLogoOverrides();if(v)map[x.name]=v;else delete map[x.name];setJSON('lighterBrandLogoOverrides',map);openBrand(x.name,currentEditIndex,null,'replace');render()};const file=detail.querySelector('#brandLogoFile');if(file)file.onchange=async()=>{const f=file.files?.[0];if(!f)return;try{const data=await fileToLogoDataURL(f),map=brandLogoOverrides();map[x.name]=data;setJSON('lighterBrandLogoOverrides',map);openBrand(x.name,currentEditIndex,null,'replace');render()}catch(e){alert(e.message||'Logo 圖片處理失敗')}};const reset=detail.querySelector('#resetBrandLogo');if(reset)reset.onclick=()=>{const map=brandLogoOverrides();delete map[x.name];setJSON('lighterBrandLogoOverrides',map);openBrand(x.name,currentEditIndex,null,'replace');render()};const del=detail.querySelector('#deleteCustomBrand');if(del)del.onclick=()=>{if(!confirm(`刪除自訂品牌「${displayBrandName(x.name)}」？\n這也會刪除該品牌的型號與收藏資料。`))return;setJSON('lighterCustomBrands',customBrands().filter(b=>canonicalBrandName(b.name)!==x.name));const db=models();delete db[x.name];setJSON('lighterModels',db);setJSON('lighterSaved',saved().filter(n=>n!==x.name));for(const key of ['lighterBrandRanks','lighterBrandOrigins','lighterBrandLogoOverrides','lighterBrandNotes','lighterBrandAliases']){const m=getJSON(key,{});delete m[x.name];setJSON(key,m)}rebuildBrands();closeModalDirect();renderFilters();render()}}
function addBrandFormHTML(){return `<div class="add-brand-page"><h2>＋ 新增品牌</h2><p>建立目前資料庫沒有的品牌。新增後可照一般品牌管理型號、Logo 與 Rank。</p><form id="addBrandForm" class="form"><div class="field full"><label>品牌名稱 *</label><input name="name" required placeholder="例如 Prael"></div><div class="field"><label>起源國家</label><input name="origin" placeholder="例如 德國"></div><div class="field"><label>收藏 Rank</label>${rankSelect('B','newBrandRank')}</div><div class="field full"><label>Logo 圖片網址</label><input name="logoUrl" type="url" placeholder="https://…"></div><div class="field full"><label>或上傳 Logo</label><input id="newBrandLogoFile" type="file" accept="image/*"></div><div class="form-actions full"><button type="submit">新增品牌</button><button type="button" id="cancelAddBrand" class="secondary">取消</button></div></form></div>`}
function openAddBrand(navMode='auto'){currentBrand=null;currentEditIndex=null;detail.innerHTML=addBrandFormHTML();modal.classList.remove('hidden');document.body.classList.add('lock');detail.querySelector('#cancelAddBrand').onclick=()=>{if(history.state?.addBrand)history.back();else closeModalDirect()};detail.querySelector('#addBrandForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),name=canonicalBrandName((fd.get('name')||'').trim());if(!name)return;const duplicate=all.some(x=>norm(x.name)===norm(name)||norm(displayBrandName(x.name))===norm(name));if(duplicate)return alert('這個品牌已經在資料庫裡了。');const origin=(fd.get('origin')||'').trim(),rank=detail.querySelector('#newBrandRank').value,arr=customBrands();arr.push({name,origin,region:origin,tier:rank,type:'自訂品牌',note:'',custom:true});setJSON('lighterCustomBrands',arr);const logoUrl=(fd.get('logoUrl')||'').trim(),file=detail.querySelector('#newBrandLogoFile').files?.[0],logos=brandLogoOverrides();if(file){try{logos[name]=await fileToLogoDataURL(file)}catch(err){alert(err.message||'Logo 處理失敗')}}else if(logoUrl&&safeUrl(logoUrl))logos[name]=logoUrl;if(logos[name])setJSON('lighterBrandLogoOverrides',logos);rebuildBrands();renderFilters();render();openBrand(name,null,null,'replace')};if(navMode==='push'||navMode==='auto')history.pushState({...navState(),addBrand:true},'',location.href)}
function card(x){let on=saved().includes(x.name),ownedCount=(models()[x.name]||[]).map(normalizeModel).filter(m=>m.owned).length;return `<article class="card brandcard brandcard-v116" data-brand="${esc(x.name)}"><div class="brandcard-main"><div class="brandcard-left">${brandLogoHTML(x.name,'card')}<div class="brandcard-copy"><div class="name">${esc(displayBrandName(x.name))}</div><div class="origin">${esc(originLabel(x))}</div></div></div><div class="brandcard-right"><div class="tier">${esc(x.tier)}</div><div class="brand-owned-count" aria-label="已收藏 ${ownedCount}">${ownedCount}</div><button class="star ${on?'saved':''}" data-star="${esc(x.name)}">★</button></div></div></article>`}
function bindCards(){results.querySelectorAll('.brandcard').forEach(c=>c.onclick=e=>{if(e.target.closest('.star'))return;openBrand(c.dataset.brand)});results.querySelectorAll('.star').forEach(b=>b.onclick=e=>{e.stopPropagation();let s=saved(),n=b.dataset.star;s=s.includes(n)?s.filter(x=>x!==n):[...s,n];setJSON('lighterSaved',s);render()})}
function selectOptions(arr,value,empty='請選擇'){return `<option value="">${empty}</option>`+arr.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}
function aliasPanelHTML(name){const aliases=brandAliases(name),built=new Set((BUILTIN_ALIASES[name]||[]).map(norm));return `<section class="alias-card"><div class="alias-head"><div><b>🏷 品牌別名 / 搜尋名稱</b><small>輸入別名也能找到這個品牌；內建別名不可刪除，你新增的可以移除。</small></div></div><div class="alias-chips">${aliases.length?aliases.map(a=>`<span class="alias-chip ${built.has(norm(a))?'builtin':''}">${esc(a)}${built.has(norm(a))?'':`<button type="button" data-alias-del="${esc(a)}">×</button>`}</span>`).join(''):'<span class="alias-empty">尚無別名</span>'}</div><div class="alias-add"><input id="aliasInput" placeholder="例如：Kawee / Art Metal Works"><button type="button" id="addAliasBtn">＋ 新增別名</button></div></section>`}
function bindAliases(name){const input=detail.querySelector('#aliasInput'),btn=detail.querySelector('#addAliasBtn');if(btn&&input)btn.onclick=()=>{const v=input.value.trim();if(!v)return;const map=userAliases(),arr=map[name]||[];if(!brandAliases(name).some(x=>norm(x)===norm(v)))arr.push(v);map[name]=arr;setJSON('lighterBrandAliases',map);openBrand(name)};detail.querySelectorAll('[data-alias-del]').forEach(b=>b.onclick=()=>{const map=userAliases(),arr=map[name]||[];map[name]=arr.filter(x=>norm(x)!==norm(b.dataset.aliasDel));setJSON('lighterBrandAliases',map);openBrand(name)})}
function maintenancePanelHTML(name,index,m){m=normalizeModel(m);if(!m.owned)return `<section class="maintenance-panel"><div class="maintenance-title"><b>🔧 保養 / 維修紀錄</b></div><p class="maintenance-empty">這筆型號目前未勾選「已收藏」。勾選並儲存後即可建立保養紀錄。</p></section>`;const rows=m.maintenance||[];return `<section class="maintenance-panel"><div class="maintenance-title"><div><b>🔧 保養 / 維修紀錄</b><small>${esc(m.collectionNo||'')} · ${rows.length} 筆</small></div></div><form id="maintenanceForm" class="maintenance-form"><div class="field"><label>日期</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>項目</label><select name="type">${selectOptions(MAINTENANCE_TYPES,'','請選擇')}</select></div><div class="field"><label>費用</label><input name="cost" type="number" min="0" step="0.01" inputmode="decimal" placeholder="例如 300"></div><div class="field"><label>幣別</label><select name="currency">${selectOptions(CURRENCY_OPTIONS,m.currency||'TWD','請選擇')}</select></div><div class="field full"><label>店家 / 維修者</label><input name="shop" placeholder="例如 自己保養 / 某維修店"></div><div class="field full"><label>內容 / 備註</label><textarea name="note" placeholder="例如：更換火石並清理火輪；原件保留…"></textarea></div><button class="full" type="submit">＋ 新增紀錄</button></form><div class="maintenance-list">${rows.length?rows.slice().reverse().map((r,rev)=>{const i=rows.length-1-rev;return `<article class="maintenance-row"><div><small>${esc(r.date||'未填日期')} · ${esc(r.type||'未分類')}</small><b>${esc(r.note||r.type||'保養紀錄')}</b><span>${r.cost!==''&&r.cost!=null?`${esc(r.currency||'TWD')} ${esc(Number(r.cost).toLocaleString())}`:''}${r.shop?`${r.cost!==''?' · ':''}${esc(r.shop)}`:''}</span></div><button type="button" class="danger" data-maint-del="${i}">刪除</button></article>`}).join(''):'<p class="maintenance-empty">還沒有保養 / 維修紀錄。</p>'}</div></section>`}
function bindMaintenance(name,index){if(index===null)return;const form=detail.querySelector('#maintenanceForm');if(form)form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),db=models(),m=normalizeModel(db[name][index]);m.maintenance=[...(m.maintenance||[]),{id:uid(),date:fd.get('date')||'',type:fd.get('type')||'',cost:fd.get('cost')||'',currency:fd.get('currency')||m.currency||'TWD',shop:(fd.get('shop')||'').trim(),note:(fd.get('note')||'').trim(),created:new Date().toISOString()}];db[name][index]=m;setJSON('lighterModels',db);openBrand(name,index);render()};detail.querySelectorAll('[data-maint-del]').forEach(b=>b.onclick=()=>{if(!confirm('刪除這筆保養 / 維修紀錄？'))return;const db=models(),m=normalizeModel(db[name][index]);m.maintenance.splice(+b.dataset.maintDel,1);db[name][index]=m;setJSON('lighterModels',db);openBrand(name,index);render()})}
function potentialDuplicate(arr,model,skipIndex=null){const n=norm(model).replace(/[^a-z0-9\u4e00-\u9fff]+/g,'');if(!n)return null;return arr.find((m,i)=>i!==skipIndex&&norm(normalizeModel(m).model).replace(/[^a-z0-9\u4e00-\u9fff]+/g,'')===n)||null}
function modelFormHTML(name,m=null,index=null){const x=m?normalizeModel(m):normalizeModel({});const editing=index!==null;return `<form id="modelForm" class="form model-form" data-id="${esc(x.id)}">
  <div class="field full"><label>型號名稱 *</label><div class="input-with-action"><input name="model" required value="${esc(x.model)}" placeholder="例如 Standard / Single Claw"><button type="button" id="googleModelBtn" class="inline-search">Google 搜尋</button></div><small class="field-hint">輸入型號後可直接搜尋「品牌＋型號＋介紹」。</small></div>
  <div class="field full"><label>看到這個型號的網頁</label><input name="url" type="url" value="${esc(x.url)}" placeholder="https://…"></div>
  <label class="favorite-toggle ${x.favorite?'is-favorite':''}"><input id="favoriteInput" name="favorite" type="checkbox" ${x.favorite?'checked':''}><span class="favorite-heart flame-toggle-icon">🔥</span><span><b>加入我的最愛</b><small>適合先記下想找、想買或值得追蹤的型號</small></span></label>
  <details class="research-details" ${x.estimatedDate||x.mechanism||x.researchNotes?'open':''}><summary>顯示型號辨識 / 研究資訊</summary><div class="research-fields"><div class="field"><label>推測年代 / 年份</label><input name="estimatedDate" value="${esc(x.estimatedDate)}" placeholder="例如 1930s / 1950–1955"></div>
  <div class="field"><label>機構 / 類型</label><input name="mechanism" value="${esc(x.mechanism)}" placeholder="例如 Semi-Automatic / Petrol"></div>
  <div class="field full"><label>AI / 研究筆記</label><textarea name="researchNotes" placeholder="年份辨識、真偽疑點、刻字、AI 初判等研究資訊">${esc(x.researchNotes)}</textarea></div></div></details>
  <label class="owned-toggle ${x.owned?'is-owned':''}"><input id="ownedInput" name="owned" type="checkbox" ${x.owned?'checked':''}><span class="owned-box">✓</span><span><b>我已收藏這個型號</b><small>勾選後可填購買資料與上傳收藏照片</small></span></label>
  <section id="collectionFields" class="collection-fields ${x.owned?'':'hidden-fields'}">
    <div class="collection-title">📦 收藏資料</div><div class="collection-id-card"><label for="collectionNoInput">收藏編號</label><input id="collectionNoInput" name="collectionNo" value="${esc(x.collectionNo)}" placeholder="留空則自動產生，例如 L0001"><small>可自行修改，例如 R-001、TH-01；留空時會自動依序產生，且不可與其他收藏重複。</small></div>
    <div class="field"><label>購買年分</label><input name="purchaseYear" type="number" min="1800" max="2100" inputmode="numeric" value="${esc(x.purchaseYear)}" placeholder="例如 2026"></div>
    <div class="field"><label>購買日期</label><input name="purchaseDate" type="date" value="${esc(x.purchaseDate)}"></div>
    <div class="field"><label>價錢</label><input name="price" type="number" min="0" step="0.01" inputmode="decimal" value="${esc(x.price)}" placeholder="例如 1800"></div>
    <div class="field"><label>幣別</label><select name="currency">${selectOptions(CURRENCY_OPTIONS,x.currency,'請選擇幣別')}</select></div>
    <div class="field full"><label>來源</label><select id="sourceSelect" name="source">${selectOptions(SOURCE_OPTIONS,x.source,'請選擇購買來源')}</select></div>
    <div id="sourceOtherWrap" class="field full ${x.source==='其他'?'':'conditional-hidden'}"><label>其他來源</label><input name="sourceOther" value="${esc(x.sourceOther)}" placeholder="請輸入來源"></div>
    <div class="field"><label>賣家 / 店家</label><input name="seller" value="${esc(x.seller)}" placeholder="可留空"></div>
    <div class="field"><label>購買地點 / 國家</label><input name="purchaseLocation" value="${esc(x.purchaseLocation)}" placeholder="例如 日本大阪"></div>
    <div class="field"><label>品相</label><select name="condition">${selectOptions(CONDITION_OPTIONS,x.condition,'請選擇品相')}</select></div>
    <div class="field"><label>序號 / 刻字</label><input name="serial" value="${esc(x.serial)}" placeholder="底部刻字、序號等"></div>
    <div class="field full"><label>收藏備註</label><textarea name="notes" placeholder="只放其他補充，不用再把價格、來源塞在這裡">${esc(x.notes)}</textarea></div>
    <div class="field full photo-field"><label>收藏照片 <small>最多 5 張，會存在你的手機 / 瀏覽器</small></label><input id="photoInput" name="photos" type="file" accept="image/*" multiple><div id="photoPreview" class="photo-preview"></div>${editing?'<label class="remove-photo"><input id="removePhotos" type="checkbox"> 刪除這個型號目前所有照片</label>':''}</div>
  </section>
  <div class="form-actions"><button type="submit">${editing?'儲存修改':'＋ 新增型號'}</button>${editing?'<button type="button" id="cancelEdit" class="secondary">取消編輯</button>':''}</div>
</form>`}
function openBrand(name,editIndex=null,prefill=null,navMode='auto'){
  const x=all.find(a=>a.name===name);if(!x)return;
  const sameState=currentBrand===name&&currentEditIndex===editIndex;
  const arr=models()[name]||[],editing=editIndex!==null?arr[editIndex]:null,formData=editing||(prefill?normalizeModel(prefill):null);
  const modelList=arr.length?arr.map((m,i)=>modelRow(m,i,name)).join(''):'<div class="empty small">目前還沒有型號，看到喜歡的就加進來。</div>';
  detail.innerHTML=`<div class="detailhead brand-detail-head compact-brand-head">${brandLogoHTML(x.name,'detail')}<div class="brand-detail-copy"><div class="brand-head-line"><h2>${esc(displayBrandName(x.name))}</h2><div class="tier">${esc(x.tier)}</div></div><div class="region">${esc(originLabel(x))}</div></div></div><details class="brand-section brand-model-list" open><summary><span>已收錄型號</span><b>${arr.length}</b></summary><div class="brand-section-body"><div id="modelList">${modelList}</div></div></details><details class="brand-section brand-add-section" ${editing||prefill?'open':''}><summary><span>${editing?'編輯型號':'＋ 新增型號'}</span><small>${editing?'正在修改現有資料':'需要時再展開'}</small></summary><div class="brand-section-body">${modelFormHTML(name,formData,editIndex)}${editing?maintenancePanelHTML(name,editIndex,editing):''}</div></details>${brandSettingsHTML(x)}<details class="brand-section brand-info-section"><summary><span>品牌資料 / 辨識</span><small>別名、年份、真偽與研究來源</small></summary><div class="brand-section-body">${aliasPanelHTML(name)}${brandGuideHTML(x)}</div></details>`;
  bindBrandLogos(detail);modal.classList.remove('hidden');document.body.classList.add('lock');currentBrand=name;currentEditIndex=editIndex;bindAliases(name);bindBrandGuide(name);bindBrandSettings(x);bindModelForm(name,editIndex);bindMaintenance(name,editIndex);bindModelActions(name);loadAllModelPhotos(name);if(editing)loadEditPhotos(editing.id);
  if(navMode==='push'||(navMode==='auto'&&!sameState))history.pushState(navState(),'',location.href);else if(navMode==='replace')history.replaceState(navState(),'',location.href)}
function bindBrandGuide(name){const saveBtn=detail.querySelector('#saveBrandGuideNote'),ta=detail.querySelector('#brandGuideNote');if(saveBtn&&ta)saveBtn.onclick=()=>{const d=brandNotes();d[name]=ta.value;setJSON('lighterBrandNotes',d);saveBtn.textContent='✓ 已儲存';setTimeout(()=>saveBtn.textContent='儲存品牌筆記',1200)}}
function triggerFlameBurst(el){if(!el)return;el.classList.remove('flame-burst');void el.offsetWidth;el.classList.add('flame-burst');setTimeout(()=>el.classList.remove('flame-burst'),850)}
function toggleFavoriteVisual(form){const input=form?.querySelector('#favoriteInput'),toggle=form?.querySelector('.favorite-toggle');if(!input||!toggle)return;toggle.classList.toggle('is-favorite',input.checked)}
function bindModelForm(name,editIndex){const form=document.querySelector('#modelForm'),owned=form.querySelector('#ownedInput'),fields=form.querySelector('#collectionFields'),toggle=form.querySelector('.owned-toggle'),source=form.querySelector('#sourceSelect'),sourceOther=form.querySelector('#sourceOtherWrap'),date=form.elements.purchaseDate,year=form.elements.purchaseYear,photoInput=form.querySelector('#photoInput'),googleBtn=form.querySelector('#googleModelBtn'),favoriteInput=form.querySelector('#favoriteInput'),favoriteToggle=form.querySelector('.favorite-toggle');
  // Some mobile browsers/PWA caches previously left an invisible layer over the form. Force real form controls to receive focus/clicks.
  form.querySelectorAll('input,textarea,select,button,summary').forEach(el=>{el.style.pointerEvents='auto'});
  toggleFavoriteVisual(form);
  if(favoriteInput&&favoriteToggle){favoriteInput.onchange=()=>{toggleFavoriteVisual(form);if(favoriteInput.checked)triggerFlameBurst(favoriteToggle)};favoriteToggle.addEventListener('click',()=>setTimeout(()=>toggleFavoriteVisual(form),0));}
  googleBtn.onclick=()=>{const model=form.elements.model.value.trim(),query=model?`${name} ${model} lighter introduction identification`:`${name} lighter models catalog`;window.open(googleUrl(query),'_blank','noopener')};
  const refreshOwned=()=>{fields.classList.toggle('hidden-fields',!owned.checked);toggle.classList.toggle('is-owned',owned.checked)};owned.onchange=refreshOwned;refreshOwned();
  source.onchange=()=>sourceOther.classList.toggle('conditional-hidden',source.value!=='其他');
  date.onchange=()=>{if(date.value&&!year.value)year.value=date.value.slice(0,4)};
  photoInput.onchange=()=>previewSelectedPhotos(photoInput.files);
  if(editIndex!==null)form.querySelector('#cancelEdit').onclick=()=>{if(currentBrand===name&&currentEditIndex!==null)history.back();else openBrand(name,null,null,'replace')};
  form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),db=models(),arr=db[name]||[],existing=editIndex!==null?normalizeModel(arr[editIndex]):null,id=existing?.id||form.dataset.id||uid(),ownedNow=fd.get('owned')==='on';
    let collectionNo=ownedNow?String(fd.get('collectionNo')||'').trim():String(existing?.collectionNo||'').trim();if(ownedNow&&!collectionNo)collectionNo=existing?.collectionNo||nextCollectionNo(db);if(ownedNow&&collectionNoExists(collectionNo,db,id)){alert(`收藏編號「${collectionNo}」已被其他收藏使用，請換一個編號。`);return}const rec=normalizeModel({...(existing||{}),id,collectionNo,model:fd.get('model').trim(),url:fd.get('url').trim(),favorite:fd.get('favorite')==='on',estimatedDate:fd.get('estimatedDate').trim(),mechanism:fd.get('mechanism').trim(),researchNotes:fd.get('researchNotes').trim(),owned:ownedNow,purchaseYear:ownedNow?fd.get('purchaseYear').trim():'',purchaseDate:ownedNow?fd.get('purchaseDate').trim():'',price:ownedNow?fd.get('price').trim():'',currency:ownedNow?fd.get('currency'):'TWD',source:ownedNow?fd.get('source'):'',sourceOther:ownedNow?fd.get('sourceOther').trim():'',seller:ownedNow?fd.get('seller').trim():'',purchaseLocation:ownedNow?fd.get('purchaseLocation').trim():'',condition:ownedNow?fd.get('condition'):'未評估',serial:ownedNow?fd.get('serial').trim():'',notes:ownedNow?fd.get('notes').trim():''});
    const dup=potentialDuplicate(arr,rec.model,editIndex);if(dup&&!confirm(`可能已經收錄相同型號「${dup.model}」。仍要${editIndex!==null?'儲存':'新增'}嗎？`))return;
    if(editIndex!==null)arr[editIndex]=rec;else arr.push(rec);db[name]=arr;setJSON('lighterModels',db);
    try{let current=await getPhotos(id);if(form.querySelector('#removePhotos')?.checked)current=[];const files=[...photoInput.files].slice(0,5);if(ownedNow&&files.length){const room=Math.max(0,5-current.length),fresh=[];for(const f of files.slice(0,room))fresh.push(await compressImage(f));current=[...current,...fresh]}if(current.length)await putPhotos(id,current);else await deletePhotos(id)}catch(err){console.error(err);alert('型號已儲存，但照片處理失敗。可以稍後再編輯上傳。')}
    openBrand(name,null,null,'replace');render();
  }
}
async function previewSelectedPhotos(files){const p=document.querySelector('#photoPreview');if(!p)return;p.innerHTML='';for(const f of [...files].slice(0,5)){const url=URL.createObjectURL(f),img=document.createElement('img');img.src=url;img.onload=()=>URL.revokeObjectURL(url);p.appendChild(img)}}
async function loadEditPhotos(id){const p=document.querySelector('#photoPreview');if(!p)return;try{const ps=await getPhotos(id);for(const blob of ps){const url=URL.createObjectURL(blob),img=document.createElement('img');img.src=url;img.onload=()=>URL.revokeObjectURL(url);p.appendChild(img)}}catch{}}
function formatPrice(m){if(m.price===''||m.price==null)return'';const n=Number(m.price),v=Number.isFinite(n)?n.toLocaleString():m.price;return `${m.currency||''} ${v}`.trim()}
function sourceLabel(m){return m.source==='其他'?(m.sourceOther||'其他'):m.source}
function dataLine(label,value){return value?`<div class="data-line"><span>${esc(label)}</span><b>${esc(value)}</b></div>`:''}
function modelRow(m,i,name){m=normalizeModel(m);const u=safeUrl(m.url);return `<div class="modelrow ${m.owned?'owned-row':''} ${m.favorite?'favorite-row':''}" data-model-id="${esc(m.id)}"><div class="modeltop"><div class="model-badges"><label class="owned-pill ${m.owned?'on':''}"><input type="checkbox" data-own="${i}" ${m.owned?'checked':''}><span class="box">✓</span><b>${m.owned?'已收藏':'未收藏'}</b></label>${m.owned&&m.collectionNo?`<span class="collection-number">${esc(m.collectionNo)}</span>`:''}<button type="button" class="model-fav ${m.favorite?'on':''}" data-model-fav="${i}" title="我的最愛">🔥</button></div><div class="row-actions">${m.owned?`<button type="button" class="edit maintenance-open" data-maint-open="${i}">保養</button>`:''}<button type="button" class="edit" data-model-edit="${i}">編輯</button><button type="button" class="danger" data-del="${i}">刪除</button></div></div><div class="modelname">${esc(m.model)}</div>${m.estimatedDate||m.mechanism||m.authenticity?`<div class="research-chips">${m.estimatedDate?`<span>📅 ${esc(m.estimatedDate)}</span>`:''}${m.mechanism?`<span>⚙ ${esc(m.mechanism)}</span>`:''}${m.authenticity?`<span>🔎 ${esc(m.authenticity)}</span>`:''}</div>`:''}${m.researchNotes?`<div class="research-note"><span>AI / 研究筆記</span><p>${esc(m.researchNotes)}</p></div>`:''}${(m.maintenance?.length||m.aiHistoryIds?.length)?`<div class="record-chips">${m.maintenance?.length?`<span>🔧 保養 ${m.maintenance.length} 筆</span>`:''}${m.aiHistoryIds?.length?`<span>✦ AI ${m.aiHistoryIds.length} 筆</span>`:''}</div>`:''}${m.owned?`<div class="collection-data">${dataLine('收藏編號',m.collectionNo)}${dataLine('購買年分',m.purchaseYear)}${dataLine('購買日期',m.purchaseDate)}${dataLine('價錢',formatPrice(m))}${dataLine('來源',sourceLabel(m))}${dataLine('賣家 / 店家',m.seller)}${dataLine('購買地點 / 國家',m.purchaseLocation)}${dataLine('品相',m.condition&&m.condition!=='未評估'?m.condition:'')}${dataLine('序號 / 刻字',m.serial)}${m.notes?`<div class="data-note"><span>收藏備註</span><p>${esc(m.notes)}</p></div>`:''}</div><div class="photo-gallery" data-photo-id="${esc(m.id)}"></div>`:''}${u?`<a class="source" href="${esc(u)}" target="_blank" rel="noopener">開啟型號來源網頁 ↗</a>`:''}</div>`}
async function loadAllModelPhotos(name){const arr=models()[name]||[];for(const m0 of arr){const m=normalizeModel(m0);if(!m.owned)continue;const box=detail.querySelector(`[data-photo-id="${CSS.escape(m.id)}"]`);if(!box)continue;try{const ps=await getPhotos(m.id);for(const blob of ps){const url=URL.createObjectURL(blob),img=document.createElement('img');img.src=url;img.alt=m.model;img.onclick=()=>window.open(url,'_blank');box.appendChild(img)}}catch{}}}
function bindModelActions(name){detail.querySelectorAll('[data-maint-open]').forEach(el=>el.onclick=e=>{e.stopPropagation();openBrand(name,+el.dataset.maintOpen);setTimeout(()=>detail.querySelector('.maintenance-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),60)});detail.querySelectorAll('[data-own]').forEach(el=>el.onchange=()=>{let db=models();const i=+el.dataset.own;db[name][i]=normalizeModel(db[name][i]);db[name][i].owned=el.checked;if(el.checked&&!db[name][i].collectionNo)db[name][i].collectionNo=nextCollectionNo(db);setJSON('lighterModels',db);openBrand(name);render()});detail.querySelectorAll('[data-model-fav]').forEach(el=>el.onclick=()=>{const willOn=!el.classList.contains('on');if(willOn)triggerFlameBurst(el);setTimeout(()=>{let db=models();const i=+el.dataset.modelFav;db[name][i]=normalizeModel(db[name][i]);db[name][i].favorite=!db[name][i].favorite;setJSON('lighterModels',db);openBrand(name);render()},willOn?180:0)});detail.querySelectorAll('[data-model-edit]').forEach(el=>el.onclick=e=>{e.stopPropagation();openBrand(name,+el.dataset.modelEdit)});detail.querySelectorAll('[data-del]').forEach(el=>el.onclick=async()=>{if(!confirm('確定刪除這筆型號？'))return;let db=models(),m=normalizeModel(db[name][+el.dataset.del]);db[name].splice(+el.dataset.del,1);setJSON('lighterModels',db);await deletePhotos(m.id).catch(()=>{});openBrand(name);render()})}

function aiEndpoint(){return (localStorage.getItem('lighterAIEndpoint')||'').trim().replace(/\/+$/,'')}
function setAIEndpoint(v){const clean=(v||'').trim().replace(/\/+$/,'');if(clean)localStorage.setItem('lighterAIEndpoint',clean);else localStorage.removeItem('lighterAIEndpoint');return clean}
function findBrandMatch(name){const n=norm(name);if(!n||n==='未知')return null;let exact=all.find(x=>[x.name,...brandAliases(x.name)].some(v=>norm(v)===n));if(exact)return exact;let contain=all.find(x=>[x.name,...brandAliases(x.name)].some(v=>norm(v).includes(n)||n.includes(norm(v))));if(contain)return contain;const toks=n.split(/[^a-z0-9]+/).filter(x=>x.length>=4);let best=null,score=0;for(const x of all){const hay=norm([x.name,...brandAliases(x.name)].join(' ')),s=toks.filter(t=>hay.includes(t)).length;if(s>score){best=x;score=s}}return score?best:null}
function aiList(title,arr){return Array.isArray(arr)&&arr.length?`<div class="ai-block"><b>${esc(title)}</b><ul>${arr.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}
function estimateAICost(data){const u=data?.usage||{},input=Number(u.input_tokens||0),output=Number(u.output_tokens||0),model=data?.model||'';let inRate=0,outRate=0;if(model.includes('luna')){inRate=.20;outRate=1.20}else if(model.includes('sol')){inRate=4;outRate=20}else return null;const cost=input/1e6*inRate+output/1e6*outRate;return {cost,input,output}}
function recordAICost(data){const e=estimateAICost(data);if(!e)return;const log=getJSON('lighterAICostLog',[]);log.push({date:new Date().toISOString(),model:data.model,cost:e.cost,input:e.input,output:e.output});setJSON('lighterAICostLog',log.slice(-1000))}
function monthAICost(){const ym=new Date().toISOString().slice(0,7);return getJSON('lighterAICostLog',[]).filter(x=>(x.date||'').startsWith(ym)).reduce((n,x)=>n+Number(x.cost||0),0)}
function aiCostHTML(data){const e=estimateAICost(data);if(!e)return '';return `<div class="ai-cost"><b>API 用量估算</b><span>本次約 US$${e.cost.toFixed(e.cost<0.01?4:3)} · Input ${e.input.toLocaleString()} / Output ${e.output.toLocaleString()} tokens</span><small>僅為此 App 的模型 token 粗估，不等於正式帳單；深入模式的 Web Search 等工具費可能另計。 <a href="https://platform.openai.com/usage" target="_blank" rel="noopener">查看 OpenAI Usage ↗</a></small></div>`}
function aiResearchNotes(a){const lines=[];if(a.summary)lines.push('AI 摘要：'+a.summary);if(a.authenticity)lines.push('真偽 / 原裝初判：'+a.authenticity+(a.authenticity_reason?' — '+a.authenticity_reason:''));if(Array.isArray(a.visible_markings)&&a.visible_markings.length)lines.push('可見刻字：'+a.visible_markings.join('；'));if(Array.isArray(a.concerns)&&a.concerns.length)lines.push('疑點：'+a.concerns.join('；'));return lines.join('\n')}
async function saveAIToDB(data,{owned=false,favorite=false}={}){const a=data?.analysis||{},match=findBrandMatch(a.brand);if(!match)throw new Error('資料庫找不到對應品牌');let db=models(),arr=db[match.name]||[],src=(data.sources||[]).find(s=>safeUrl(s.url)),rec=normalizeModel({collectionNo:owned?nextCollectionNo(db):'',model:a.model&&a.model!=='未知'?a.model:'AI 未確定型號',url:src?.url||'',owned,favorite,estimatedDate:a.date_range&&a.date_range!=='未知'?a.date_range:'',mechanism:a.mechanism&&a.mechanism!=='未知'?a.mechanism:'',authenticity:a.authenticity||'',researchNotes:aiResearchNotes(a),aiHistoryIds:data?._historyId?[data._historyId]:[]});const dup=potentialDuplicate(arr,rec.model);if(dup&&!confirm(`資料庫已有可能相同的型號「${dup.model}」。仍要新增 AI 辨識結果嗎？`))throw new Error('已取消新增');arr.push(rec);db[match.name]=arr;setJSON('lighterModels',db);if(owned){let ps=[];if(data?._historyId){try{ps=await getPhotos('aihist-'+data._historyId)}catch{ps=[]}}if(!ps.length&&aiFiles.length){for(const f of aiFiles.slice(0,5))ps.push(await compressImage(f))}if(ps.length)await putPhotos(rec.id,ps.slice(0,5))}return {brand:match.name,index:arr.length-1,rec}}
function aiResultHTML(data){const a=data?.analysis||{},match=findBrandMatch(a.brand),sources=Array.isArray(data?.sources)?data.sources:[],authClass=a.authenticity==='較符合真品特徵'?'good':a.authenticity==='有疑點'?'warn':'neutral';return `<section class="ai-result"><div class="ai-result-head"><div><small>AI 照片初判</small><h2>${esc(a.brand||'未知')} ${a.model&&a.model!=='未知'?`<span>${esc(a.model)}</span>`:''}</h2></div><div class="confidence">把握：${esc(a.confidence||'—')}</div></div><div class="ai-facts"><div><span>推測年代</span><b>${esc(a.date_range||'未知')}</b></div><div><span>國家</span><b>${esc(a.country||'未知')}</b></div><div><span>機構</span><b>${esc(a.mechanism||'未知')}</b></div><div><span>分析模型</span><b>${esc(data.model||'—')}</b></div></div>${aiCostHTML(data)}<div class="auth-box ${authClass}"><span>真偽 / 原裝初判</span><strong>${esc(a.authenticity||'無法判定')}</strong><p>${esc(a.authenticity_reason||'')}</p></div>${a.summary?`<div class="ai-summary">${esc(a.summary)}</div>`:''}${aiList('看得到的刻字 / 標記',a.visible_markings)}${aiList('支持判斷的特徵',a.evidence)}${aiList('疑點 / 需要注意',a.concerns)}${aiList('建議補拍',a.missing_photos)}${sources.length?`<div class="ai-sources"><b>網路查證來源</b>${sources.map(s=>`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener">${esc(s.title||s.url)} ↗</a>`).join('')}</div>`:''}<div class="ai-actions ai-actions-v10">${match?`<select id="aiSaveMode"><option value="model">只記錄型號</option><option value="favorite">加入我的最愛</option><option value="owned">加入我的收藏</option></select><button id="aiSaveToDb">＋ 加入資料庫</button>`:`<button type="button" disabled>資料庫目前找不到對應品牌</button>`}<button type="button" id="aiGoogleResult" class="secondary">Google 再查一次</button></div><p class="ai-disclaimer">AI 只能根據照片與可查到的資料做初判；高價、稀有或疑似重製品仍建議比對實物、專利、型錄與可靠收藏資料。</p></section>`}
async function saveAIHistory(data,{mode='quick',hint=''}={}){const entry={id:uid(),date:new Date().toISOString(),mode,hint,analysis:data?.analysis||{},sources:Array.isArray(data?.sources)?data.sources:[],model:data?.model||'',usage:data?.usage||null};const hist=aiHistory();hist.unshift(entry);setJSON('lighterAIHistory',hist.slice(0,120));return entry}
function historyResult(h){return {analysis:h.analysis||{},sources:h.sources||[],model:h.model||'',usage:h.usage||null,_historyId:h.id}}
function aiHistoryHTML(){const hist=aiHistory();return `<section class="ai-history"><div class="ai-history-head"><div><h3>✦ AI 辨識歷史</h3><p>每次成功分析會自動保留文字結果；完整原圖不再重複保存，避免浪費空間。</p></div><span>${hist.length} 筆</span></div>${hist.length?`<div class="ai-history-list">${hist.slice(0,30).map(h=>{const a=h.analysis||{};return `<article class="ai-history-row"><div class="ai-history-thumbs" data-aihist-photos="${esc(h.id)}"></div><button type="button" class="ai-history-main" data-aihist-view="${esc(h.id)}"><small>${esc(new Date(h.date).toLocaleString())} · ${h.mode==='deep'?'深入':'快速'}</small><b>${esc(a.brand||'未知')} ${a.model&&a.model!=='未知'?esc(a.model):''}</b><span>${esc(a.date_range||'年代未知')} · ${esc(a.authenticity||'無法判定')}</span></button><button type="button" class="danger" data-aihist-del="${esc(h.id)}">刪除</button></article>`}).join('')}</div>`:'<div class="ai-empty compact"><b>尚無 AI 歷史</b><span>完成第一次辨識後會自動出現在這裡。</span></div>'}</section>`}
async function loadAIHistoryThumbs(){for(const box of document.querySelectorAll('[data-aihist-photos]')){try{const ps=await getPhotos('aihist-'+box.dataset.aihistPhotos);box.innerHTML='';for(const p of ps.slice(0,2)){const img=document.createElement('img'),u=URL.createObjectURL(p);img.src=u;img.onload=()=>URL.revokeObjectURL(u);box.appendChild(img)}}catch{}}}
function bindAIHistory(){document.querySelectorAll('[data-aihist-view]').forEach(b=>b.onclick=()=>{const h=aiHistory().find(x=>x.id===b.dataset.aihistView);if(!h)return;aiLastResult=historyResult(h);renderAI();setTimeout(()=>document.querySelector('#aiOutput')?.scrollIntoView({behavior:'smooth',block:'start'}),50)});document.querySelectorAll('[data-aihist-del]').forEach(b=>b.onclick=async()=>{if(!confirm('刪除這筆 AI 辨識歷史？'))return;const id=b.dataset.aihistDel;setJSON('lighterAIHistory',aiHistory().filter(x=>x.id!==id));await deletePhotos('aihist-'+id).catch(()=>{});let db=models(),changed=false;for(const brand of Object.keys(db)){db[brand]=db[brand].map(m0=>{const m=normalizeModel(m0),before=m.aiHistoryIds.length;m.aiHistoryIds=m.aiHistoryIds.filter(x=>x!==id);if(before!==m.aiHistoryIds.length)changed=true;return m})}if(changed)setJSON('lighterModels',db);renderAI()});loadAIHistoryThumbs()}
function renderAIFilePreview(){const box=document.querySelector('#aiPhotoPreview');if(!box)return;box.innerHTML=aiFiles.map((f,i)=>`<div class="ai-photo"><img data-ai-preview="${i}" alt="待辨識照片"><button type="button" data-ai-remove="${i}">×</button></div>`).join('');box.querySelectorAll('[data-ai-preview]').forEach(img=>{const f=aiFiles[+img.dataset.aiPreview],u=URL.createObjectURL(f);img.src=u;img.onload=()=>URL.revokeObjectURL(u)});box.querySelectorAll('[data-ai-remove]').forEach(b=>b.onclick=()=>{aiFiles.splice(+b.dataset.aiRemove,1);renderAIFilePreview();updateAIPhotoCount()});updateAIPhotoCount()}
function updateAIPhotoCount(){const el=document.querySelector('#aiPhotoCount');if(el)el.textContent=`${aiFiles.length} / 6 張`}
function addAIFiles(files){for(const f of files){if(!f.type.startsWith('image/'))continue;if(aiFiles.length>=6)break;aiFiles.push(f)}renderAIFilePreview()}
async function aiImageDataURLs(){const out=[];for(const f of aiFiles.slice(0,6)){const blob=await compressImage(f);out.push(await blobToDataURL(blob))}return out}
function updateAISetupBadge(state='saved'){const b=document.querySelector('#aiSetupBadge');if(!b)return;const has=!!aiEndpoint();if(state==='connected'){b.textContent='已連線';b.className='setup-ok'}else if(has){b.textContent='已設定';b.className='setup-ok'}else{b.textContent='尚未設定';b.className='setup-needed'}}
async function testAIConnection(){const endpoint=aiEndpoint(),box=document.querySelector('#aiConnectionStatus');if(!endpoint){box.textContent='請先輸入 Worker 網址。';box.className='connection bad';updateAISetupBadge();return}box.textContent='測試連線中…';box.className='connection';updateAISetupBadge();try{const r=await fetch(endpoint+'/health',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'連線失敗');box.textContent='✓ AI 後端連線正常';box.className='connection good';updateAISetupBadge('connected')}catch(e){box.textContent='✕ '+(e.message||'無法連線');box.className='connection bad';updateAISetupBadge()}}
function bindAIResult(data){const a=data?.analysis||{},match=findBrandMatch(a.brand);document.querySelector('#aiGoogleResult')?.addEventListener('click',()=>window.open(googleUrl(`${a.brand||''} ${a.model||''} lighter identification authenticity dating`),'_blank','noopener'));const b=document.querySelector('#aiSaveToDb');if(b&&match)b.onclick=async()=>{const mode=document.querySelector('#aiSaveMode')?.value||'model',opts=mode==='owned'?{owned:true,favorite:false}:mode==='favorite'?{owned:false,favorite:true}:{owned:false,favorite:false},old=b.textContent;b.disabled=true;b.textContent='儲存中…';try{const r=await saveAIToDB(data,opts);b.textContent='✓ 已加入資料庫';render();if(opts.owned)openBrand(r.brand,r.index)}catch(e){alert(e.message||String(e));b.disabled=false;b.textContent=old}}}
async function runAIAnalysis(){const endpoint=aiEndpoint(),btn=document.querySelector('#aiAnalyze'),out=document.querySelector('#aiOutput'),mode=document.querySelector('#aiMode')?.value||'quick',hint=document.querySelector('#aiHint')?.value||'';if(!endpoint){alert('請先在 AI 設定填入 Cloudflare Worker 網址。');return}if(!aiFiles.length){alert('請先拍照或選擇至少一張照片。');return}const old=btn.textContent;btn.disabled=true;btn.textContent=mode==='deep'?'正在深入查證…':'正在辨識照片…';out.innerHTML='<div class="ai-loading"><div class="spinner"></div><b>AI 正在看照片</b><span>辨識底印、機構與刻字，請稍候。</span></div>';try{const images=await aiImageDataURLs(),headers={'Content-Type':'application/json'};const r=await fetch(endpoint+'/analyze',{method:'POST',headers,body:JSON.stringify({images,mode,hint,catalog:all.map(x=>x.name)})}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||`HTTP ${r.status}`);recordAICost(d);const hist=await saveAIHistory(d,{mode,hint});d._historyId=hist.id;aiLastResult=d;out.innerHTML=aiResultHTML(d);bindAIResult(d);const histWrap=document.querySelector('.ai-history');if(histWrap){histWrap.outerHTML=aiHistoryHTML();bindAIHistory()}}catch(e){console.error(e);out.innerHTML=`<div class="ai-error"><b>辨識失敗</b><p>${esc(e.message||String(e))}</p><small>如果是 401 / quota / billing 錯誤，通常要回 OpenAI Platform 檢查 API key 或 API 餘額。</small></div>`}finally{btn.disabled=false;btn.textContent=old}}
function renderAI(){const endpoint=aiEndpoint();results.innerHTML=`<section class="ai-page"><div class="ai-hero"><div class="ai-icon">✦</div><div><h2>AI 打火機辨識</h2><p>拍攝正面、底印、鉸鏈與點火機構，AI 會嘗試辨識品牌、型號、年代並做真偽 / 原裝風險初判。</p></div></div><details class="ai-config" ${endpoint?'':'open'}><summary>⚙ AI 後端設定 <span id="aiSetupBadge" class="${endpoint?'setup-ok':'setup-needed'}">${endpoint?'已設定':'尚未設定'}</span></summary><div class="field"><label>Cloudflare Worker 網址</label><input id="aiEndpointInput" type="url" value="${esc(endpoint)}" placeholder="https://lighter-db-ai.xxxxx.workers.dev"><small>这里只存 Worker 網址，不是 OpenAI API key。API key 絕對不要放進這個 App 或 GitHub。</small></div><div class="config-actions"><button id="saveAIEndpoint">儲存網址</button><button id="testAIEndpoint" class="secondary">測試連線</button></div><div id="aiConnectionStatus" class="connection"></div></details><div class="ai-capture card"><h3>① 拍攝 / 選擇照片</h3><p class="fineprint">最多 6 張。最好包含：全貌、底部刻字、Logo、鉸鏈、火輪 / 點火機構、加油口或內膽。</p><div class="capture-buttons"><label class="capture-btn">📷 直接拍照<input id="aiCamera" type="file" accept="image/*" capture="environment"></label><label class="capture-btn secondary">▣ 從相簿選擇<input id="aiAlbum" type="file" accept="image/*" multiple></label></div><div class="ai-photo-meta"><span id="aiPhotoCount">0 / 6 張</span><button type="button" id="aiClearPhotos">清除全部</button></div><div id="aiPhotoPreview" class="ai-photo-preview"></div></div><div class="ai-options card"><h3>② 分析設定</h3><div class="field"><label>你已知的線索（選填）</label><textarea id="aiHint" placeholder="例如：賣家說是 Thorens、底部看到 PAT. 1912、疑似重新鍍鉻…"></textarea></div><div class="field"><label>分析模式</label><select id="aiMode"><option value="quick">快速辨識 — GPT-5.6 Luna（較省）</option><option value="deep">深入鑑定 — GPT-5.6 Sol + 網路查證</option></select></div><button id="aiAnalyze" class="ai-analyze">✦ 開始 AI 辨識</button></div><div id="aiOutput">${aiLastResult?aiResultHTML(aiLastResult):'<div class="ai-empty"><b>還沒有辨識結果</b><span>先拍幾張打火機照片，再按「開始 AI 辨識」。</span></div>'}</div>${aiHistoryHTML()}</section>`;document.querySelector('#saveAIEndpoint').onclick=()=>{const v=setAIEndpoint(document.querySelector('#aiEndpointInput').value);document.querySelector('#aiEndpointInput').value=v;updateAISetupBadge();testAIConnection()};document.querySelector('#testAIEndpoint').onclick=testAIConnection;document.querySelector('#aiCamera').onchange=e=>{addAIFiles([...e.target.files]);e.target.value=''};document.querySelector('#aiAlbum').onchange=e=>{addAIFiles([...e.target.files]);e.target.value=''};document.querySelector('#aiClearPhotos').onclick=()=>{aiFiles=[];renderAIFilePreview()};document.querySelector('#aiAnalyze').onclick=runAIAnalysis;renderAIFilePreview();if(aiLastResult)bindAIResult(aiLastResult);bindAIHistory()}

function favoriteModels(){const out=[];const db=models();for(const [brand,arr] of Object.entries(db))arr.forEach((m,i)=>{m=normalizeModel(m);if(m.favorite)out.push({brand,m,index:i})});return out}
function renderFavorites(){filters.style.display='none';q.parentElement.style.display='none';status.textContent='';const brands=all.filter(x=>saved().includes(x.name)),mods=favoriteModels();results.innerHTML=`<div class="favorites-page"><h2>🔥 我的最愛</h2><p>把想追蹤的品牌與型號集中在這裡；「最愛」不等於已收藏。</p><h3>最愛品牌 <span class="count-pill">${brands.length}</span></h3><div class="favorite-brand-grid">${brands.length?brands.map(card).join(''):'<div class="empty small">還沒有最愛品牌。到資料庫按品牌右側 ★。</div>'}</div><h3>最愛型號 <span class="count-pill">${mods.length}</span></h3><div class="favorite-models">${mods.length?mods.map(({brand,m,index})=>`<article class="favorite-model-card" data-fav-brand="${esc(brand)}" data-fav-index="${index}"><button class="fav-heart on" data-unfav-brand="${esc(brand)}" data-unfav-index="${index}">🔥</button><small>${esc(displayBrandName(brand))}</small><h3>${esc(m.model)}</h3>${m.estimatedDate?`<div>📅 ${esc(m.estimatedDate)}</div>`:''}${m.mechanism?`<div>⚙ ${esc(m.mechanism)}</div>`:''}${m.owned?'<span class="owned-tag">✓ 已收藏</span>':'<span class="watch-tag">想找 / 追蹤</span>'}</article>`).join(''):'<div class="empty small">還沒有最愛型號。品牌頁或 AI 辨識結果都可以按 🔥。</div>'}</div></div>`;bindCards();bindBrandLogos(results);results.querySelectorAll('.favorite-model-card').forEach(c=>c.onclick=e=>{if(e.target.closest('[data-unfav-brand]'))return;openBrand(c.dataset.favBrand,+c.dataset.favIndex)});results.querySelectorAll('[data-unfav-brand]').forEach(b=>b.onclick=e=>{e.stopPropagation();const brand=b.dataset.unfavBrand,i=+b.dataset.unfavIndex,db=models();db[brand][i]=normalizeModel(db[brand][i]);db[brand][i].favorite=false;setJSON('lighterModels',db);renderFavorites()})}


function ownedRecords(){const out=[],db=models();for(const [brand,arr] of Object.entries(db))arr.forEach((m0,index)=>{const m=normalizeModel(m0);if(m.owned)out.push({brand,m,index,brandInfo:all.find(x=>x.name===brand)||null})});return out}
function countBy(rows,getter){const map=new Map();for(const r of rows){const k=getter(r)||'未分類';map.set(k,(map.get(k)||0)+1)}return [...map.entries()].sort((a,b)=>b[1]-a[1]||String(a[0]).localeCompare(String(b[0])))}
function statBars(title,rows,limit=8){if(!rows.length)return `<section class="stat-panel"><h3>${esc(title)}</h3><div class="stat-empty">尚無資料</div></section>`;const max=Math.max(...rows.map(x=>x[1]));return `<section class="stat-panel"><h3>${esc(title)}</h3><div class="bar-list">${rows.slice(0,limit).map(([name,n])=>`<div class="bar-row"><div class="bar-label"><span>${esc(name)}</span><b>${n}</b></div><div class="bar-track"><i style="width:${Math.max(5,n/max*100)}%"></i></div></div>`).join('')}</div></section>`}
function moneyStats(rows){const by={};for(const {m} of rows){const n=Number(m.price);if(!Number.isFinite(n)||n<0||m.price==='')continue;const c=m.currency||'未指定';if(!by[c])by[c]={sum:0,count:0};by[c].sum+=n;by[c].count++}return Object.entries(by).sort((a,b)=>b[1].sum-a[1].sum)}
function renderStats(){filters.style.display='none';q.parentElement.style.display='none';status.textContent='';const rows=ownedRecords(),favCount=favoriteModels().length,brandCount=new Set(rows.map(r=>r.brand)).size,withPrice=rows.filter(r=>r.m.price!==''&&Number.isFinite(Number(r.m.price))).length,money=moneyStats(rows),brandRows=countBy(rows,r=>r.brand),regionRows=countBy(rows,r=>r.brandInfo?.region||'未分類'),tierRows=countBy(rows,r=>r.brandInfo?.tier||'未分類'),sourceRows=countBy(rows,r=>sourceLabel(r.m)||'未填來源'),yearRows=countBy(rows,r=>r.m.purchaseYear||(r.m.purchaseDate||'').slice(0,4)||'未填年份');const recent=[...rows].sort((a,b)=>String(b.m.purchaseDate||b.m.added).localeCompare(String(a.m.purchaseDate||a.m.added))).slice(0,6);results.innerHTML=`<section class="stats-page"><div class="stats-hero"><div><small>MY COLLECTION</small><h2>▥ 收藏統計</h2><p>只統計已勾選「已收藏」的型號；最愛仍維持原本獨立狀態。</p></div></div><div class="stat-cards"><div><span>已收藏</span><b>${rows.length}</b><small>件</small></div><div><span>收藏品牌</span><b>${brandCount}</b><small>個</small></div><div><span>最愛型號</span><b>${favCount}</b><small>筆</small></div><div><span>保養 / 維修</span><b>${rows.reduce((n,r)=>n+(r.m.maintenance?.length||0),0)}</b><small>筆</small></div></div>${money.length?`<section class="stat-panel"><h3>購入金額</h3><p class="stat-note">不同幣別不混加，避免匯率造成錯誤。</p><div class="money-grid">${money.map(([cur,v])=>`<div><span>${esc(cur)}</span><b>${Number(v.sum).toLocaleString(undefined,{maximumFractionDigits:2})}</b><small>${v.count} 件 · 平均 ${Number(v.sum/v.count).toLocaleString(undefined,{maximumFractionDigits:2})}</small></div>`).join('')}</div></section>`:''}<div class="stats-grid">${statBars('品牌數量',brandRows)}${statBars('收藏 Tier',tierRows)}${statBars('品牌地區',regionRows)}${statBars('購買來源',sourceRows)}${statBars('購買年份',yearRows)}</div><section class="stat-panel"><h3>最近加入收藏</h3>${recent.length?`<div class="recent-list">${recent.map(r=>`<button data-stat-brand="${esc(r.brand)}" data-stat-index="${r.index}"><span class="collection-number">${esc(r.m.collectionNo||'—')}</span><div><b>${esc(r.brand)} · ${esc(r.m.model)}</b><small>${esc(r.m.purchaseDate||r.m.purchaseYear||'未填購買日期')}${r.m.price!==''?' · '+esc(formatPrice(r.m)):''}</small></div><span>›</span></button>`).join('')}</div>`:'<div class="stat-empty">還沒有已收藏資料。</div>'}</section></section>`;results.querySelectorAll('[data-stat-brand]').forEach(b=>b.onclick=()=>openBrand(b.dataset.statBrand,+b.dataset.statIndex))}


const commonsFile=(name)=>'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(name);
const commonsPage=(name)=>'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(name);
const KNOWLEDGE_PHOTOS={
  history:[
    {src:commonsFile('Döbereiner fire gadget.png'),caption:'1823 年 Döbereiner 氫氣打火裝置的結構圖。這種設計和後來的口袋煤油機不同，但很適合理解「打火機」早期發展。',credit:'Wikimedia Commons · Public Domain',page:commonsPage('Döbereiner fire gadget.png')}
  ],
  mechanisms:[
    {src:commonsFile('Disassembled butane lighter (5).jpg'),caption:'丁烷打火機拆解圖：可以直接看到氣槽、噴嘴、點火模組與外殼不是煤油棉芯結構。',credit:'Suyash Dwivedi · CC BY-SA 4.0',page:commonsPage('Disassembled butane lighter (5).jpg')},
    {src:commonsFile('Piezo igniter.jpg'),caption:'壓電點火器本體。按下時產生高壓火花，因此不需要傳統火石輪。',credit:'Wikimedia Commons',page:commonsPage('Piezo igniter.jpg')},
    {src:commonsFile('Flint spark lighter striking.jpg'),caption:'火石輪點火時的火花。若打火機上看得到火輪與火石管，多半屬於這一類機構。',credit:'Phyzome · CC BY-SA 3.0',page:commonsPage('Flint spark lighter striking.jpg')}
  ],
  maintenance:[
    {src:commonsFile('Zippo Vintage serisi çakmak.jpg'),caption:'外殼與內膽分離的實例。煤油機保養時，要先理解哪些是外殼、內膽、棉芯與火石相關部位。',credit:'Wikimedia Commons',page:commonsPage('Zippo Vintage serisi çakmak.jpg')}
  ],
  storage:[
    {src:commonsFile('Vintage Smoking Set In Presentation Box - Ashtray, Cigarette Holder & Cigarette Lighter, No Manufacturer Markings (18187337763).jpg'),caption:'原盒／成套配件也是收藏完整度的一部分。保存時最好讓金屬件彼此不直接磨擦。',credit:'Joe Haupt · CC BY-SA 2.0',page:commonsPage('Vintage Smoking Set In Presentation Box - Ashtray, Cigarette Holder & Cigarette Lighter, No Manufacturer Markings (18187337763).jpg')}
  ],
  collecting:[
    {src:commonsFile('Cigarette Lighter Collection 2 (8490962168).jpg'),caption:'不同品牌、年代與外型混合收藏的實例。收藏主題不一定只能綁在單一品牌。',credit:'Joe Haupt · CC BY-SA 2.0',page:commonsPage('Cigarette Lighter Collection 2 (8490962168).jpg')}
  ],
  authentication:[
    {src:commonsFile('Zippo bottom.jpg'),caption:'底印是年代與真偽判斷的重要證據之一。要看字體、排版、日期碼、產地與其他細節是否同時吻合。',credit:'Hu Totya · CC BY 3.0 / GFDL',page:commonsPage('Zippo bottom.jpg')}
  ],
  buying:[
    {src:commonsFile('Zippo open.jpg'),caption:'買中古打火機時，不只拍正面；頂部、鉸鏈、火輪與火口常比外殼圖案更能辨識型號與機構。',credit:'Hu Totya · CC BY 3.0 / GFDL',page:commonsPage('Zippo open.jpg')}
  ],
  safety:[
    {src:commonsFile('White lighter with flame.JPG'),caption:'補油、加氣、測漏與拆修時都應遠離已點燃的火焰與高熱源。',credit:'Kimmo Palosaari · Public Domain',page:commonsPage('White lighter with flame.JPG')}
  ],
  checklist:[
    {src:commonsFile('Vintage Cigarette Case and Lighter, Souvenir of Gibraltar, No Manufacturer Markings (10500953605).jpg'),caption:'無品牌／陌生款更需要逐項記錄外型、底印、機構、材質與配件，不能只靠外觀猜品牌。',credit:'Joe Haupt · CC BY-SA 2.0',page:commonsPage('Vintage Cigarette Case and Lighter, Souvenir of Gibraltar, No Manufacturer Markings (10500953605).jpg')}
  ]
};
function knowledgePhotosHTML(id,title){
  const ps=KNOWLEDGE_PHOTOS[id]||[];if(!ps.length)return '';
  return `<div class="knowledge-photo-grid">${ps.map((p,i)=>`<figure class="knowledge-photo"><a href="${esc(safeUrl(p.page))}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(safeUrl(p.src))}" alt="${esc(title)} 參考照片 ${i+1}"></a><figcaption><span>${esc(p.caption)}</span><small>圖片：${esc(p.credit)}</small></figcaption></figure>`).join('')}</div>`
}
function knowledgeArticleHTML(k){return `<details class="knowledge-card" data-knowledge="${esc(k.id)}"><summary><span class="knowledge-icon">${esc(k.icon)}</span><div><h3>${esc(k.title)}</h3><p>${esc(k.summary)}</p></div><span class="knowledge-arrow">⌄</span></summary><div class="knowledge-body">${knowledgePhotosHTML(k.id,k.title)}${(k.sections||[]).map(s=>`<section><h4>${esc(s.title)}</h4><p>${esc(s.body)}</p></section>`).join('')}${k.sources?.length?`<div class="knowledge-sources"><b>延伸資料</b>${k.sources.map(a=>`<a href="${esc(safeUrl(a.url))}" target="_blank" rel="noopener">${esc(a.name)} ↗</a>`).join('')}</div>`:''}</div></details>`}
function knowledgeLinksHTML(){const a=links();return `<details class="knowledge-card resource-card"><summary><span class="knowledge-icon">↗</span><div><h3>資料庫與收藏社群</h3><p>把原本的參考資料整合進知識區，避免導航列太碎。</p></div><span class="knowledge-arrow">⌄</span></summary><div class="knowledge-body"><div id="knowledgeLinks">${a.map((l,i)=>`<div class="linkrow"><div><b>${esc(l.name)}</b>${l.note?`<div class="note">${esc(l.note)}</div>`:''}<a class="source" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">開啟網站 ↗</a></div><button class="danger" data-klinkdel="${i}">刪除</button></div>`).join('')}</div><form id="knowledgeLinkForm" class="form compact-form"><div class="field"><label>網站名稱</label><input name="name" required></div><div class="field"><label>網址</label><input name="url" type="url" required></div><div class="field full"><label>用途 / 備註</label><input name="note"></div><button class="full">＋ 新增參考網址</button></form></div></details>`}
function bindKnowledgeLinks(){const f=document.querySelector('#knowledgeLinkForm');if(f)f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),a=links();a.push({name:fd.get('name').trim(),url:fd.get('url').trim(),note:fd.get('note').trim()});setJSON('lighterLinks',a);renderKnowledge()};document.querySelectorAll('[data-klinkdel]').forEach(b=>b.onclick=()=>{if(confirm('刪除這個網址？')){const a=links();a.splice(+b.dataset.klinkdel,1);setJSON('lighterLinks',a);renderKnowledge()}})}
function renderKnowledge(){filters.style.display='none';q.parentElement.style.display='none';status.textContent='';results.innerHTML=`<section class="knowledge-page"><div class="knowledge-hero"><small>LIGHTER KNOWLEDGE</small><h2><span class="mono-title-icon">▤</span>打火機知識庫</h2><p>歷史、機構、保養、保存、收藏與辨識的基礎手冊。內容以收藏安全與「保留原裝」為優先。</p></div><div class="knowledge-search"><input id="knowledgeSearch" placeholder="搜尋：火石、丁烷、保養、真偽、歷史…"><button id="knowledgeClear">×</button></div><div class="knowledge-warning">⚠ 古董打火機的材質、密封與機構差異很大；知識庫提供一般原則，稀有或高價品拆修前仍應查該型號資料。</div><div id="knowledgeList">${KNOWLEDGE.map(knowledgeArticleHTML).join('')}${knowledgeLinksHTML()}</div></section>`;bindKnowledgeLinks();const input=document.querySelector('#knowledgeSearch'),list=document.querySelector('#knowledgeList');const apply=()=>{const t=norm(input.value.trim());const data=!t?KNOWLEDGE:KNOWLEDGE.filter(k=>norm([k.title,k.summary,...(k.sections||[]).flatMap(s=>[s.title,s.body])].join(' ')).includes(t));list.innerHTML=(data.length?data.map(knowledgeArticleHTML).join(''):'<div class="empty small">找不到符合的知識文章。</div>')+(!t?knowledgeLinksHTML():'');bindKnowledgeLinks()};input.oninput=apply;document.querySelector('#knowledgeClear').onclick=()=>{input.value='';input.focus();apply()}}

function renderLinks(){let a=links();results.innerHTML=`<div class="about"><h2>參考資料</h2><p>把常用的收藏資料庫、論壇、文章或賣場放在這裡。</p><form id="linkForm" class="form"><div class="field"><label>網站名稱</label><input name="name" required placeholder="例如 Lighter Library"></div><div class="field"><label>網址</label><input name="url" type="url" required placeholder="https://…"></div><div class="field full"><label>用途 / 備註</label><input name="note" placeholder="例如：查製造商、專利、型錄"></div><button class="full">＋ 新增網址</button></form><div>${a.map((l,i)=>`<div class="linkrow"><div><b>${esc(l.name)}</b>${l.note?`<div class="note">${esc(l.note)}</div>`:''}<a class="source" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">開啟網站 ↗</a></div><button class="danger" data-linkdel="${i}">刪除</button></div>`).join('')}</div></div>`;document.querySelector('#linkForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),a=links();a.push({name:fd.get('name').trim(),url:fd.get('url').trim(),note:fd.get('note').trim()});setJSON('lighterLinks',a);render()};results.querySelectorAll('[data-linkdel]').forEach(b=>b.onclick=()=>{if(confirm('刪除這個網址？')){let a=links();a.splice(+b.dataset.linkdel,1);setJSON('lighterLinks',a);render()}})}
async function exportBackup(){const db=models(),photos={};for(const arr of Object.values(db)){for(const m0 of arr){const m=normalizeModel(m0);try{const ps=await getPhotos(m.id);if(ps.length)photos[m.id]=await Promise.all(ps.map(blobToDataURL))}catch{}}}for(const h of aiHistory()){try{const ps=await getPhotos('aihist-'+h.id);if(ps.length)photos['aihist-'+h.id]=await Promise.all(ps.map(blobToDataURL))}catch{}}const data={version:12.3,exported:new Date().toISOString(),saved:saved(),models:db,links:links(),brandNotes:brandNotes(),brandAliases:userAliases(),customBrands:customBrands(),brandRanks:brandRankOverrides(),brandOrigins:brandOriginOverrides(),brandLogoOverrides:brandLogoOverrides(),aiEndpoint:aiEndpoint(),aiCostLog:getJSON('lighterAICostLog',[]),aiHistory:aiHistory(),photos},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`lighter-db-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importBackupFile(f){const text=await f.text(),d=JSON.parse(text);if(d.saved)setJSON('lighterSaved',d.saved);if(d.models)setJSON('lighterModels',d.models);if(d.links)setJSON('lighterLinks',d.links);if(d.brandNotes)setJSON('lighterBrandNotes',d.brandNotes);if(d.brandAliases)setJSON('lighterBrandAliases',d.brandAliases);if(d.customBrands)setJSON('lighterCustomBrands',d.customBrands);if(d.brandRanks)setJSON('lighterBrandRanks',d.brandRanks);if(d.brandOrigins)setJSON('lighterBrandOrigins',d.brandOrigins);if(d.brandLogoOverrides)setJSON('lighterBrandLogoOverrides',d.brandLogoOverrides);if(d.aiEndpoint)setAIEndpoint(d.aiEndpoint);if(d.aiCostLog)setJSON('lighterAICostLog',d.aiCostLog);if(d.aiHistory)setJSON('lighterAIHistory',d.aiHistory);rebuildBrands();renderFilters();ensureModelIds();ensureCollectionNumbers();if(d.photos){for(const [id,arr] of Object.entries(d.photos)){await putPhotos(id,arr.map(dataURLToBlob))}}}
function renderBackup(){results.innerHTML=`<section class="backup-page"><div class="backup-hero"><small>LOCAL BACKUP</small><h2>⇅ 備份</h2><p>收藏、照片、最愛、維修紀錄、Alias 與 AI 歷史都主要保存在目前裝置。定期匯出一份完整 JSON 備份最穩。</p></div><div class="backup-card"><h3>完整備份</h3><p>匯出檔會包含目前 App 的收藏資料與本機照片；照片越多，檔案越大。</p><div class="backup"><button id="exportBtn">↓ 匯出完整備份（含照片）</button><label class="import">↑ 匯入備份<input id="importFile" type="file" accept="application/json"></label></div><p class="fineprint">建議：每次大量新增收藏或照片後匯出一次，並把檔案存到 Google Drive、iCloud、OneDrive 或電腦。</p></div><div class="backup-card"><h3>資料安全提醒</h3><ul><li>GitHub 只放 App 程式，不會自動包含你存在瀏覽器裡的收藏資料與照片。</li><li>OpenAI API key 仍保存在 Cloudflare Secret，不在這份備份內。</li><li>換手機、清除瀏覽器網站資料或重設裝置前，務必先匯出備份。</li></ul></div></section>`;document.querySelector('#exportBtn').onclick=async e=>{const b=e.currentTarget,old=b.textContent;b.disabled=true;b.textContent='正在整理備份…';try{await exportBackup()}finally{b.disabled=false;b.textContent=old}};document.querySelector('#importFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{await importBackupFile(f);alert('備份已匯入');render()}catch(err){console.error(err);alert('這不是有效的 Lighter DataBase 備份檔，或檔案已損壞。')}}}
function navState(extra={}){return {lighterDB:true,view,brand:currentBrand,editIndex:currentEditIndex,sidebar:false,...extra}}
function closeModalDirect(){modal.classList.add('hidden');document.body.classList.remove('lock');currentBrand=null;currentEditIndex=null}
function applyNavState(state){const s=state&&state.lighterDB?state:{lighterDB:true,view:'db',brand:null,editIndex:null,sidebar:false,addBrand:false};closeSidebarDirect();view=s.view||'db';currentBrand=null;currentEditIndex=null;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.querySelectorAll('[data-side-view]').forEach(x=>x.classList.toggle('active',x.dataset.sideView===view));closeModalDirect();render();if(s.addBrand)openAddBrand('none');else if(s.brand)openBrand(s.brand,s.editIndex??null,null,'none');if(s.sidebar)openSidebarDirect()}
function render(){if(view==='mine'){renderFavorites();return}if(view==='stats'){renderStats();return}if(view==='knowledge'){renderKnowledge();return}if(view==='backup'){filters.style.display='none';q.parentElement.style.display='none';status.textContent='';renderBackup();return}if(view==='ai'){filters.style.display='none';q.parentElement.style.display='none';status.textContent='';renderAI();return}filters.style.display='flex';q.parentElement.style.display='flex';let data=all;let term=norm(q.value.trim());if(term)data=data.filter(x=>norm([x.name,displayBrandName(x.name),originLabel(x),...brandAliases(x.name)].join(' ')).includes(term));if(tier!=='全部')data=data.filter(x=>x.tier===tier);status.textContent=`找到 ${data.length} 筆${term?' · 搜尋「'+q.value.trim()+'」':''}`;const cards=data.length?data.map(card).join(''):`<div class="empty"><b>${term?'目前資料庫沒有找到':'這裡目前是空的'}</b>${term?'這不代表它不是品牌。你可以直接新增品牌。':'點品牌右側 ★ 就能加入品牌收藏。'}</div>`;results.innerHTML=`<div class="database-actions"><button id="addBrandBtn" type="button">＋ 新增品牌</button></div>${cards}`;document.querySelector('#addBrandBtn').onclick=()=>openAddBrand();bindCards();bindBrandLogos(results)}
q.oninput=render;document.querySelector('#clear').onclick=()=>{q.value='';q.focus();render()};const menuBtn=document.querySelector('#menuBtn'),sidebar=document.querySelector('#sidebar'),sidebarScrim=document.querySelector('#sidebarScrim'),closeSidebarBtn=document.querySelector('#closeSidebar');function openSidebarDirect(){sidebar.classList.add('open');sidebarScrim.classList.remove('hidden');sidebar.setAttribute('aria-hidden','false');menuBtn.setAttribute('aria-expanded','true');document.body.classList.add('sidebar-lock')}function closeSidebarDirect(){sidebar.classList.remove('open');sidebarScrim.classList.add('hidden');sidebar.setAttribute('aria-hidden','true');menuBtn.setAttribute('aria-expanded','false');document.body.classList.remove('sidebar-lock')}function openSidebar(){if(sidebar.classList.contains('open'))return;openSidebarDirect();history.pushState(navState({sidebar:true}),'',location.href)}function closeSidebar(){if(sidebar.classList.contains('open')&&history.state?.sidebar)history.back();else closeSidebarDirect()}menuBtn.onclick=openSidebar;closeSidebarBtn.onclick=closeSidebar;sidebarScrim.onclick=closeSidebar;function setView(next){if(!next)return;const sidebarWasOpen=sidebar.classList.contains('open')&&history.state?.sidebar;closeSidebarDirect();if(next===view&&!currentBrand){if(sidebarWasOpen)history.replaceState(navState(),'',location.href);return}view=next;closeModalDirect();document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===next));document.querySelectorAll('[data-side-view]').forEach(x=>x.classList.toggle('active',x.dataset.sideView===next));render();if(sidebarWasOpen)history.replaceState(navState(),'',location.href);else history.pushState(navState(),'',location.href)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-side-view]').forEach(b=>b.onclick=()=>setView(b.dataset.sideView));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(sidebar.classList.contains('open'))closeSidebar();else if(currentBrand)history.back()}});function closeModalFromUI(){if(history.state?.brand||history.state?.addBrand){history.back();setTimeout(()=>{if(!modal.classList.contains('hidden'))closeModalDirect()},220)}else closeModalDirect()}const closeModalBtn=document.querySelector('#closeModal');closeModalBtn.onclick=e=>{e.preventDefault();e.stopPropagation();closeModalFromUI()};closeModalBtn.addEventListener('touchend',e=>{e.preventDefault();e.stopPropagation();closeModalFromUI()},{passive:false});modal.onclick=e=>{if(e.target===modal)closeModalFromUI()};window.addEventListener('popstate',e=>applyNavState(e.state));renderFilters();render();history.replaceState(navState(),'',location.href);if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
